export type MatchCardProps = {
    match: Pick<Match, "id" | "matched_at"> & {
        first: Pick<Horse, "id" | "name">;
        second: Pick<Horse, "id" | "name">;
    };
};

export async function readMatchCard(match: Match): Promise<MatchCardProps> {
    const [first, second] = await Promise.all([
        must(horses.get(match.first_id)),
        must(horses.get(match.second_id)),
    ]);
    return {
        match: {
            id: match.id,
            matched_at: match.matched_at,
            first: { id: first.id, name: first.name },
            second: { id: second.id, name: second.name },
        },
    };
}
